export type StableUserAgentData = {
  brands: string[]
  mobile: boolean
  platform: string
  architecture?: string
  bitness?: string
  model?: string
  platformVersion?: string
  /**
   * Present only when high-entropy value collection was blocked by a Permissions Policy.
